import{_ as a,o as t,c as n,a0 as o}from"./chunks/framework.veCcaNqE.js";const h=JSON.parse('{"title":"Framework Example 4: Context Model Index","description":"","frontmatter":{},"headers":[],"relativePath":"examples/framework-example4/domain-models.md","filePath":"examples/framework-example4/domain-models.md"}'),i={name:"examples/framework-example4/domain-models.md"};function r(d,e,s,l,c,m){return t(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="framework-example-4-context-model-index" tabindex="-1">Framework Example 4: Context Model Index <a class="header-anchor" href="#framework-example-4-context-model-index" aria-label="Permalink to &quot;Framework Example 4: Context Model Index&quot;">​</a></h1><p><a href="/ospf/zh-cn/examples/framework-example4/domain-models.html">中文</a></p><p>Demo4 is an architecture sample rather than a complete Kotlin application: <code>Application</code> is empty and only <code>Demo4GenericQuantitySample</code> is executable. This index therefore separates context contracts from application wiring. The local model pages below are maintained model prose; data-only and orchestration contexts explicitly document their absence of independent solver variables rather than inventing a global model.</p><h2 id="_1-context-map" tabindex="-1">1. Context map <a class="header-anchor" href="#_1-context-map" aria-label="Permalink to &quot;1. Context map&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes material-theme-darker material-theme-lighter vp-code" tabindex="0"><code><span class="line"><span>task + rule + crew + cargo → bunch_generation → bunch_compilation</span></span>
<span class="line"><span>                                      ↘ bunch_selection (branch-and-price policy)</span></span>
<span class="line"><span>passenger ───────────────────────────→ bunch_compilation (optional pipelines)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>The directed arrows describe data and service dependencies, not a claim that <code>Application</code> registers every context in one model.</p><h2 id="_2-context-model-pages" tabindex="-1">2. Context model pages <a class="header-anchor" href="#_2-context-model-pages" aria-label="Permalink to &quot;2. Context model pages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Context</th><th>Model boundary</th><th>Local model</th></tr></thead><tbody><tr><td>task</td><td>flight tasks, legs, cycles, aircraft and recovery data; input to generation and compilation</td><td><a href="./domain-task/domain-model.html">task</a>; no independent optimization model is registered by <code>Application</code></td></tr><tr><td>rule</td><td>links, restrictions, flow control, and feasibility/time/cost calculators</td><td><a href="./domain-rule/domain-model.html">rule</a>; predicates used by bunch generation</td></tr><tr><td>crew</td><td>crew members, ranks, schedules, and transit-time data</td><td><a href="./domain-crew/domain-model.html">crew</a></td></tr><tr><td>cargo</td><td>cargo data and capacity/disruption placeholders</td><td><a href="./domain-cargo/domain-model.html">cargo</a></td></tr><tr><td>passenger</td><td>passenger amount, cancellation, class/flight changes and their objective/constraint pipelines</td><td><a href="./domain-passenger/domain-model.html">passenger</a></td></tr><tr><td>bunch_generation</td><td>feasible bunch/column generation from task/rule/crew/cargo data and shadow prices</td><td><a href="./domain-bunch_generation/domain-model.html">bunch generation</a>; generation service, not a standalone master model</td></tr><tr><td>bunch_compilation</td><td>master-model column selection, task/flow/fleet/link/capacity expressions and incremental columns</td><td><a href="./domain-bunch_compilation/domain-model.html">bunch compilation</a></td></tr><tr><td>bunch_selection</td><td>branch-and-price policy, reduced-cost callback and orchestration</td><td><a href="./domain-bunch_selection/domain-model.html">bunch selection</a>; algorithm service, no independent variable family</td></tr></tbody></table><h2 id="_3-shared-notation-and-master-contract" tabindex="-1">3. Shared notation and master contract <a class="header-anchor" href="#_3-shared-notation-and-master-contract" aria-label="Permalink to &quot;3. Shared notation and master contract&quot;">​</a></h2><p>Shared symbols (<code>B_k</code>, <code>T</code>, <code>A</code>, <code>L</code>) and generated-column incidence coefficients are defined in the linked context pages. The compilation page is the source of truth for registered variables, slacks, constraints, and objective; this index does not duplicate those formulas.</p><h2 id="_4-context-boundaries-and-evidence" tabindex="-1">4. Context boundaries and evidence <a class="header-anchor" href="#_4-context-boundaries-and-evidence" aria-label="Permalink to &quot;4. Context boundaries and evidence&quot;">​</a></h2><ol><li><code>BunchGenerationContext.generateFlightTaskBunch</code> is the pricing callback. It returns generated bunches for a shadow-price map; it is not a solver constraint.</li><li><code>BunchCompilationContext.register</code> creates the linear meta-model symbols and returns the active pipeline list. A model class that is not returned by that list is not an active assertion.</li><li><code>PassengerContext.register</code> is an independent registration path. It should not be silently folded into the compilation equations unless the caller invokes it.</li><li><code>BranchAndPriceAlgorithm</code> coordinates policy, bounds, reduced costs, and generated columns. It supplies algorithm state, not an additional domain variable family.</li></ol><p>The parent page documents the generic-quantity executable and provides Kotlin/Rust source entry points. Use these split pages for context-level vocabulary and formula review, and the source links below for implementation line evidence.</p><ol start="5"><li><a href="https://github.com/fuookami/ospf-kotlin/tree/main/ospf-kotlin-example/src/main/fuookami/ospf/kotlin/example/framework_demo/demo4" target="_blank" rel="noreferrer">Kotlin Demo4 source</a></li><li><a href="https://github.com/fuookami/ospf-rust/tree/main/ospf-rust-example/src/core/demo4.rs" target="_blank" rel="noreferrer">Rust Demo4 source</a></li></ol>`,14)])])}const u=a(i,[["render",r]]);export{h as __pageData,u as default};
